            __m256i pix0 = _mm256_unpacklo_epi16(pix, vmin);
            __m256i pix1 = _mm256_unpackhi_epi16(pix, vmin);
            acc = _mm256_add_pd(simd_rcp_pd(_mm256_cvtepi32_pd(_mm256_extracti128_si256(pix0, 0))), acc);
