            temp0 = _mm256_and_pd(_mm256_sub_pd(temp0, _mm256_cvtps_pd(_mm256_extractf128_ps(pix1, 0))), vabs);
            temp1 = _mm256_and_pd(_mm256_sub_pd(temp1, _mm256_cvtps_pd(_mm256_extractf128_ps(pix1, 1))), vabs);
