    acc1 = _mm256_add_epi32(acc1, _mm256_mullo_epi32(_mm256_unpackhi_epi16(temp0, zero), weight2_0));
    acc2 = _mm256_add_epi32(acc2, _mm256_mullo_epi32(_mm256_unpacklo_epi16(temp1, zero), weight2_0));
    acc3 = _mm256_add_epi32(acc3, _mm256_mullo_epi32(_mm256_unpackhi_epi16(temp1, zero), weight2_0));
