    acc1 = _mm256_add_epi32(acc1, _mm256_mullo_epi32(_mm256_unpackhi_epi16(temp0, zero), weight2_1));
    acc2 = _mm256_add_epi32(acc2, _mm256_mullo_epi32(_mm256_unpacklo_epi16(temp1, zero), weight2_1));
    acc3 = _mm256_add_epi32(acc3, _mm256_mullo_epi32(_mm256_unpackhi_epi16(temp1, zero), weight2_1));
    temp0 = _mm256_unpacklo_epi8(pix1_2, zero);
    temp1 = _mm256_unpackhi_epi8(pix1_2, zero);
    acc0 = _mm256_add_epi32(acc0, _mm256_mullo_epi32(_mm256_unpacklo_epi16(temp0, zero), weight2_2));
    acc1 = _mm256_add_epi32(acc1, _mm256_mullo_epi32(_mm256_unpackhi_epi16(temp0, zero), weight2_2));
    acc2 = _mm256_add_epi32(acc2, _mm256_mullo_epi32(_mm256_unpacklo_epi16(temp1, zero), weight2_2));
    acc3 = _mm256_add_epi32(acc3, _mm256_mullo_epi32(_mm256_unpackhi_epi16(temp1, zero), weight2_2));
    acc0 = _mm256_cvtps_epi32(_mm256_div_ps(_mm256_cvtepi32_ps(acc0), v_div));
    acc1 = _mm256_cvtps_epi32(_mm256_div_ps(_mm256_cvtepi32_ps(acc1), v_div));
    acc2 = _mm256_cvtps_epi32(_mm256_div_ps(_mm256_cvtepi32_ps(acc2), v_div));
