        acc4 = _mm256_add_epi16(_mm256_unpacklo_epi8(pix0_0, zero), _mm256_unpacklo_epi8(pix1_0, zero));
        acc5 = _mm256_add_epi16(_mm256_unpackhi_epi8(pix0_0, zero), _mm256_unpackhi_epi8(pix1_0, zero));
