        acc4 = _mm256_sub_epi16(acc4, _mm256_unpacklo_epi8(pix1_2, zero));
        acc5 = _mm256_sub_epi16(acc5, _mm256_unpackhi_epi8(pix1_2, zero));
        acc4 = _mm256_sub_epi16(acc4, _mm256_unpacklo_epi8(pix1_2, zero));
