        acc6 = _mm256_add_epi16(acc6, _mm256_unpacklo_epi8(pix1_1, zero));
        acc7 = _mm256_add_epi16(acc7, _mm256_unpackhi_epi8(pix1_1, zero));
        acc6 = _mm256_sub_epi16(acc6, _mm256_unpacklo_epi8(pix0_1, zero));
        acc7 = _mm256_sub_epi16(acc7, _mm256_unpackhi_epi8(pix0_1, zero));
        acc6 = _mm256_sub_epi16(acc6, _mm256_unpacklo_epi8(pix0_2, zero));
