    acc0 = _mm256_sub_epi16(acc0, _mm256_unpacklo_epi8(pix1_2, zero));
    acc1 = _mm256_sub_epi16(acc1, _mm256_unpackhi_epi8(pix1_2, zero));
    acc0 = _mm256_sub_epi16(acc0, _mm256_unpacklo_epi8(pix1_1, zero));
    acc1 = _mm256_sub_epi16(acc1, _mm256_unpackhi_epi8(pix1_1, zero));
