    acc2 = _mm256_sub_epi32(acc2, _mm256_unpacklo_epi16(pix1_0, zero));
    acc3 = _mm256_sub_epi32(acc3, _mm256_unpackhi_epi16(pix1_0, zero));
    acc2 = _mm256_sub_epi32(acc2, _mm256_unpacklo_epi16(pix1_1, zero));
    acc3 = _mm256_sub_epi32(acc3, _mm256_unpackhi_epi16(pix1_1, zero));
    acc2 = _mm256_sub_epi32(acc2, _mm256_unpacklo_epi16(pix1_2, zero));
    acc3 = _mm256_sub_epi32(acc3, _mm256_unpackhi_epi16(pix1_2, zero));
    acc4 = _mm256_add_epi32(_mm256_unpacklo_epi16(pix0_0, zero), _mm256_unpacklo_epi16(pix1_0, zero));
    acc5 = _mm256_add_epi32(_mm256_unpackhi_epi16(pix0_0, zero), _mm256_unpackhi_epi16(pix1_0, zero));
    acc4 = _mm256_add_epi32(acc4, _mm256_unpacklo_epi16(pix1_0, zero));
    acc5 = _mm256_add_epi32(acc5, _mm256_unpackhi_epi16(pix1_0, zero));
    acc4 = _mm256_sub_epi32(acc4, _mm256_unpacklo_epi16(pix0_2, zero));
    acc5 = _mm256_sub_epi32(acc5, _mm256_unpackhi_epi16(pix0_2, zero));
    acc4 = _mm256_sub_epi32(acc4, _mm256_unpacklo_epi16(pix1_2, zero));
