    const uint8_t* ptrs = (const uint8_t*)srcp;
    uint8_t* ptrd = (uint8_t*)dstp;
    int tail = src_w % 32;
    if (!tail) tail = 32;
    int mod32_w = src_w - tail;
    int x = 0;
    
