    max0 = _mm256_max_epi16(max0, _mm256_max_epi16(_mm256_max_epi16(acc8, acc10), _mm256_max_epi16(acc12, acc14)));
    max1 = _mm256_max_epi16(_mm256_max_epi16(acc1, acc3), _mm256_max_epi16(acc5, acc7));
    max1 = _mm256_max_epi16(max1, _mm256_max_epi16(_mm256_max_epi16(acc9, acc11), _mm256_max_epi16(acc13, acc15)));
    min0 = _mm256_min_epi16(_mm256_min_epi16(acc0, acc2), _mm256_min_epi16(acc4, acc6));
    min0 = _mm256_min_epi16(min0, _mm256_min_epi16(_mm256_min_epi16(acc8, acc10), _mm256_min_epi16(acc12, acc14)));
