    min1 = _mm256_abs_epi16(_mm256_add_epi16(_mm256_slli_epi16(min1, 3), temp1));
    acc0 = _mm256_max_epi16(max0, min0);
    acc1 = _mm256_max_epi16(max1, min1);
    _mm256_stream_si256((__m256i*)(ptrd + x), _mm256_packus_epi16(acc0, acc1));
