		pix[0] = _mm256_loadu_si256((const __m256i*)(ptrs - stride + x));
		pix[1] = _mm256_loadu_si256((const __m256i*)(ptrs + x - 1));
		pix[2] = _mm256_loadu_si256((const __m256i*)(ptrs + x));
		pix[4] = _mm256_loadu_si256((const __m256i*)(ptrs + stride + x));
		pix[3] = simd_reshuffle_epi16(pix[2], right_idx);
		temp = _mm256_max_epu16(_mm256_max_epu16(pix[0], pix[1]), _mm256_max_epu16(pix[2], pix[3]));
        temp = _mm256_max_epu16(pix[4], temp);
		_mm256_stream_si256((__m256i*)(ptrd + x), _mm256_min_epu16(temp, _mm256_adds_epu16(pix[2], v_thr)));
		
