    temp1 = _mm256_add_epi16(_mm256_unpackhi_epi8(pix[0][0], zero), _mm256_unpackhi_epi8(pix[0][1], zero));
    temp0 = _mm256_add_epi16(temp0, _mm256_unpacklo_epi8(pix[0][2], zero));
    temp1 = _mm256_add_epi16(temp1, _mm256_unpackhi_epi8(pix[0][2], zero));
