    for (int i = 0; i < 16; i++) right_arr[i] = (i < tail - 1) ? i + 1 : tail - 1;
    __m256i right_idx = _mm256_loadu_si256((const __m256i*)right_arr);
    
	__m256i pix[3][3], temp0, temp1;
	
	pix[1][1] = _mm256_loadu_si256((const __m256i*)ptrs);
	pix[1][2] = _mm256_loadu_si256((const __m256i*)(ptrs + 1));
	pix[2][1] = _mm256_loadu_si256((const __m256i*)(ptrs + stride));
	pix[2][2] = _mm256_loadu_si256((const __m256i*)(ptrs + stride + 1));
	pix[1][0] = simd_reshuffle_epi16(pix[1][1], left_idx);
	pix[2][0] = simd_reshuffle_epi16(pix[2][1], left_idx);
