    temp0 = _mm256_add_epi32(temp0, _mm256_unpacklo_epi16(pix[1][1], zero));
    temp1 = _mm256_add_epi32(temp1, _mm256_unpackhi_epi16(pix[1][1], zero));
    temp0 = _mm256_add_epi32(temp0, _mm256_slli_epi32(_mm256_unpacklo_epi16(pix[1][2], zero), 1));
    temp1 = _mm256_add_epi32(temp1, _mm256_slli_epi32(_mm256_unpackhi_epi16(pix[1][2], zero), 1));
    temp0 = _mm256_add_epi32(temp0, _mm256_unpacklo_epi16(pix[2][0], zero));
    temp1 = _mm256_add_epi32(temp1, _mm256_unpackhi_epi16(pix[2][0], zero));
