            __m256i pix1 = _mm256_load_si256((const __m256i*)(ptrs1 + x));
            __m256i res = _mm256_adds_epi8(_mm256_xor_si256(pix0, half), _mm256_xor_si256(pix1, half));
            _mm256_stream_si256((__m256i*)(ptrd + x), _mm256_xor_si256(res, half));
